insert into storage.buckets (id,name,public)
values ('site-assets','site-assets',true)
on conflict (id) do nothing;

drop policy if exists "public can view site assets" on storage.objects;
create policy "public can view site assets" on storage.objects for select using (bucket_id='site-assets');

drop policy if exists "authenticated admins can upload site assets" on storage.objects;
create policy "authenticated admins can upload site assets" on storage.objects for insert to authenticated with check (bucket_id='site-assets');

drop policy if exists "authenticated admins can update site assets" on storage.objects;
create policy "authenticated admins can update site assets" on storage.objects for update to authenticated using (bucket_id='site-assets') with check (bucket_id='site-assets');
